// Set the pixel color to an interesting procedural color generated by mixing
// and filtering Perlin noise of different frequencies.
//
// Uniforms:
uniform mat4 view;
uniform mat4 proj;
uniform float animation_seconds;
uniform bool is_moon;
// Inputs:
in vec3 sphere_fs_in;   // point on unit sphere
in vec3 normal_fs_in;
in vec4 pos_fs_in; 
in vec4 view_pos_fs_in; 
// Outputs:
out vec3 color;

// expects: blinn_phong, perlin_noise
void main()
{
  // from lit.fs
  float theta = (M_PI / 3.0) * -animation_seconds;
  float x_offset = 6.0;
  vec4 light_pos = view * vec4(x_offset * cos(theta), 6.0, x_offset * -sin(theta), 1.0);

  vec3 ka; 
  vec3 kd;
  vec3 ks;
  float p;
  vec3 n = normalize(normal_fs_in);
  vec3 v = normalize(-(view_pos_fs_in.xyz));
  vec3 l = normalize(light_pos - view_pos_fs_in).xyz;

  float p_noise;
  vec3 x, y, st;

  if (is_moon) {
    st = 3.0 * sphere_fs_in;

    // normalizes to (0, 1)
    p_noise = 0.5 + 0.5 * perlin_noise(st);

    x = vec3(0.25);
    y = vec3(0.67);
    ka = vec3(0.10);
    kd = mix(x, y, p_noise);
    ks = vec3(0.80);
    p = 60.0;
  }
  else {
    st = 50.0 * sphere_fs_in;
    x = vec3(0.10, 0.25, 0.75);
    y  = vec3(0.20, 0.60, 0.25);
    p_noise = 0.5 + 0.5 * perlin_noise(st);

    // blue bands on planet
    if (int(sphere_fs_in.y * 10.0) % 4 == 0) {
      kd = vec3(0.15, 0.30, 0.80);
    }
    // red squiggles
    else if (sin(16.0 * perlin_noise(sphere_fs_in)) > 0.9) {
      kd = vec3(0.80, 0.30, 0.15);
    }
    else {
      kd = mix(x, y, p_noise);
    }

    ka = vec3(0.04, 0.08, 0.20);
    ks = vec3(0.80);
    p = 80.0;
  }
  
  color = blinn_phong(ka, kd, ks, p, n, v, l);
}
